    debugShowCheckedModeBanner: false,
    title: 'PixelPeel',
    theme: ThemeData(useMaterial3: true, colorSchemeSeed: const Color(0xff185c49), scaffoldBackgroundColor: const Color(0xfff5f8f6)),
