  void _msg(String s)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(s)));
  @override Widget build(BuildContext c)=>Scaffold(body:SafeArea(child:Center(child:SingleChildScrollView(padding:const EdgeInsets.all(24),child:Column(children:[const Icon(Icons.eco,size:58,color:Color(0xff185c49)),const SizedBox(height:12),const Text('PixelPeel',style:TextStyle(fontSize:34,fontWeight:FontWeight.w800)),const Text('AI Onion Quality Assessment',style:TextStyle(color:Colors.grey)),const SizedBox(height:35),SegmentedButton<bool>(segments:const [ButtonSegment(value:true,label:Text('Login')),ButtonSegment(value:false,label:Text('Sign Up'))],selected:{login},onSelectionChanged:(v)=>setState(()=>login=v.first)),const SizedBox(height:22),if(!login)TextField(controller:name,decoration:const InputDecoration(labelText:'Full name',border:OutlineInputBorder())),if(!login)const SizedBox(height:12),TextField(controller:email,decoration:const InputDecoration(labelText:'Email',border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:pass,obscureText:true,decoration:const InputDecoration(labelText:'Password',border:OutlineInputBorder())),const SizedBox(height:20),SizedBox(width:double.infinity,height:52,child:FilledButton(onPressed:submit,child:Text(login?'Login':'Create Account')))]))));
}

class HomePage extends StatefulWidget { const HomePage({super.key}); @override State<HomePage> createState()=>_HomePageState(); }
